const rows = $input.all().map(i => i.json);
const now = new Date();
const DONE = /^(replied|responded|dead|closed|won|lost|unsubscribed|do not contact|no contact|appointment set|bounced|spam complaint)$/i;
const days = d => { const t = new Date(d); return isNaN(t) ? null : Math.floor((now - t) / 86400000); };
const pretty = p => { const d = String(p || '').replace(/\D/g, '').slice(-10);
  return d.length === 10 ? '(' + d.slice(0,3) + ') ' + d.slice(3,6) + '-' + d.slice(6) : String(p || ''); };

const due = [], stale = [];
for (const r of rows) {
  const status = String(r['Status'] || '').trim();
  if (DONE.test(status)) continue;
  const age = days(r['Timestamp']);
  if (age === null || age < 2 || age > 30) continue;
  const first = String(r['First Name'] || '').trim() || 'there';
  const last  = String(r['Last Name'] || '').trim();
  const addr  = String(r['Searched Address'] || '').trim();
  const where = addr ? addr.split(',')[0] : '';
  const phone = pretty(r['Phone']);
  if (!phone) continue;

  const msg2 = where
    ? "Hey " + first + ", it's Hector again. Still want to connect about " + where + ". Is morning or evening easier for a quick call? Or if texting is simpler, tell me a little about the place and I can start there."
    : "Hey " + first + ", it's Hector again. Still want to hear what you're looking for. Is morning or evening better for a quick call? Or just text me what you're after and I'll take it from there.";
  const msg12 = "Hey " + first + ", last one from me. Are you looking to sell this year, or is it more of a someday thing? Either answer is fine, I just want to know whether to keep in touch or leave you alone.";

  const base = { first, last, phone, where, age };
  if (age === 2)       due.push({ ...base, touch: 'Day 2',  msg: msg2 });
  else if (age === 12) due.push({ ...base, touch: 'Day 12', msg: msg12 });
  else if (!status)    stale.push(base);
}

if (!due.length && !stale.length) return [];

const block = d => [d.first + ' ' + d.last, d.touch, d.where].filter(Boolean).join(' \u00b7 ')
  + '\n' + d.phone + '\n\n' + d.msg;

let body = due.map(block).join('\n\n\n');

if (stale.length) {
  const tail = stale.map(d => d.first + ' ' + d.last + ' \u00b7 day ' + d.age + ' \u00b7 ' + d.phone).join('\n');
  body += (due.length ? '\n\n\n' : '') + 'No status set yet\n' + tail;
}

return [{ json: {
  count: due.length,
  staleCount: stale.length,
  body,
  subject: due.length
    ? 'Text ' + due.length + ' lead' + (due.length > 1 ? 's' : '') + ' today'
    : 'Open leads: nothing due today'
} }];

